/usr/bin/zsh -lc "node --input-type=module - <<'NODE'
import {readFileSync} from 'node:fs';
const testPath = 'src/transport/ws/messageHandler.test.ts';
const test = readFileSync(testPath, 'utf8');
const titles = new Map([...test.matchAll(/"'^'"\\s*it\\((['\""'`])(.+?)'"\\1/gm)].map(match => [match[2], test.slice(0, match.index).split('\\n').length + (match[0].startsWith('\\n') ? 1 : 0)]));
const files = [
  'specs/hal-engine-websocket-protocol/spec.md',
  'specs/hal-engine-commit-open-entries/spec.md',
  'specs/hal-engine-tool-budget/spec.md',
  'specs/hal-engine-abandon-on-close/spec.md',
  'specs/hal-engine-tool-executor-throw/spec.md',
];
let failures = 0;
for (const file of files) {
  const doc = readFileSync(file, 'utf8');
  for (const match of doc.matchAll(/\\[validated by(?:: )?(["'^'"\\]]+)\\]\\(["'^)]*messageHandler'"\\.test\\.ts#L(\\d+)\\)/g)) {
    const actual = titles.get(match[1]);
    if (actual "'!== Number(match[2])) { failures++; console.log(`${file}: ${match[1]} expected ${actual}, linked ${match[2]}`); }
  }
}
if (failures) process.exit(1);
console.log('"'all touched messageHandler citations are anchored');
